INSERT /* homes.broker.mapper.BrokerPublicMapper.insertBrokerStuff 중개사 물건(만) 추가 */
INTO   TB_BRK_STUFF (
	OFFICENO, STUFFNO, BRKNO, HPPSCD, CREAT_USER_NO, UPDT_USER_NO
) VALUES (
	#{officeno}
	, #{stuffno}
	, #{brkno}
	, #{hppscd}
	, #{brkno}
	, #{brkno}
)


INSERT /* homes.broker.mapper.BrokerPublicMapper.insertStuffComplex 중개사 물건_닩 추가 */
INTO   TB_BRK_STUFF_COMPLEX (
	OFFICENO, STUFFNO, BRKNO, HTBDNO, HPPSCD, CREAT_USER_NO, UPDT_USER_NO
) VALUES (
	#{officeno}
	, #{stuffno}
	, #{brkno}
	, #{htbdno}
	, #{hppscd}
	, #{brkno}
	, #{brkno}
)
